import { bindable } from 'aurelia-framework';
import { highlight } from './highlight';

interface RouteSources {
  sections: { [id: string]: { markup: string; ts: string; module: string } };
  files: { [path: string]: string };
  related: { [module: string]: string[] };
}

// one fetch per route, shared by every section on the page; generated by tools/gen-demo-sections.js
const routeSources: { [route: string]: Promise<RouteSources> } = {};

function sourcesFor(route: string) {
  if (!routeSources[route]) {
    routeSources[route] = fetch(`scripts/demo-src/${route}.json`).then(r => r.json()).catch(() => ({ sections: {}, files: {}, related: {} }));
  }
  return routeSources[route];
}

/** A section id can be an interpolation inside a repeat (`chart-series-${type}`), match those as patterns. */
export function findSection(sections: RouteSources['sections'], id: string) {
  if (sections[id]) { return sections[id]; }
  const key = Object.keys(sections).find(k => k.indexOf('${') >= 0 &&
    new RegExp('^' + k.split(/\$\{[^}]*\}/).map(p => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('.+') + '$').test(id));
  return key ? sections[key] : undefined;
}

/**
 * Wrapper for one feature sample on a demo page, mirrors the section layout of the Syncfusion demo site.
 * Three tabs: the live Preview (the slotted demo, kept alive while hidden), the Markup of the sample and the
 * TypeScript it uses. Markup and TypeScript each start on "this example" (just the part the sample needs) and can
 * switch to the complete file, and for TypeScript to the local files the view-model imports.
 */
export class DemoSection {
  @bindable title: string;
  @bindable description: string;
  @bindable id: string;

  tab: 'preview' | 'markup' | 'ts' = 'preview';
  tabs = [
    { key: 'preview', label: 'Preview' },
    { key: 'markup', label: 'Markup' },
    { key: 'ts', label: 'TypeScript' }
  ];
  /** what each code tab shows: 'example' or the path of a file */
  markupView = 'example';
  tsView = 'example';
  markupOptions: { value: string; label: string }[] = [];
  tsOptions: { value: string; label: string }[] = [];
  codeHtml = '';
  private sources: RouteSources;
  private module: string;

  async select(key: 'preview' | 'markup' | 'ts') {
    this.tab = key;
    if (key === 'preview') { return; }
    if (!this.sources) {
      const route = location.pathname.split('/').filter(Boolean)[0] || '';
      this.sources = await sourcesFor(route);
      const section = findSection(this.sources.sections, this.id);
      this.module = section ? section.module : '';
      const name = (path: string) => path.split('/').pop();
      this.markupOptions = [{ value: 'example', label: 'This example' }, { value: `${this.module}.html`, label: `Full ${name(this.module)}.html` }];
      this.tsOptions = [{ value: 'example', label: 'This example' }]
        .concat(this.sources.files[`${this.module}.ts`] ? [{ value: `${this.module}.ts`, label: `Full ${name(this.module)}.ts` }] : [])
        .concat((this.sources.related[this.module] || []).map(f => ({ value: f, label: name(f) })));
    }
    this.render();
  }

  viewChanged(view: string) {
    if (this.tab === 'markup') { this.markupView = view; } else { this.tsView = view; }
    this.render();
  }

  get options() { return this.tab === 'markup' ? this.markupOptions : this.tsOptions; }
  get view() { return this.tab === 'markup' ? this.markupView : this.tsView; }

  private currentText() {
    const section = this.sources && findSection(this.sources.sections, this.id);
    if (!section) { return 'No source found for this example.'; }
    const view = this.view;
    if (view === 'example') { return this.tab === 'markup' ? section.markup : section.ts; }
    return this.sources.files[view] || '';
  }

  private render() {
    this.codeHtml = highlight(this.currentText(), this.tab === 'markup' ? 'x.html' : 'x.ts');
  }

  copy() {
    const text = this.currentText();
    if (text && navigator.clipboard) { navigator.clipboard.writeText(text).catch(() => { /* clipboard blocked */ }); }
  }
}
